  const nested = executeWorkflow(
    conditionWorkflow({ all: [{ field: 'a', operator: 'gte', value: 0 }, { not: { field: 'b', operator: 'gte', value: 0 } }] }),
    { a: 1, b: { nested: true } }
  );

