    throw new Error(`condition node ${nodeId} at ${position}.${key}[${index}]: ${key}[${index}] is a missing child condition`);
  }
  children.push(
    compileCondition(childList[index], nodes, nodeId, `${position}.${key}[${index}]`, depth + 1));
}
return { kind: key, children };

